{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A1",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "data que define o início da montagem",
          "motivo": "premissa_alterada",
          "correto_seria": "A entrega do redutor continua prevista para D20, mas não define o início da montagem: com as peças da MetalForm chegando em D22, a montagem começa em D22."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A2",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a partir de D25",
          "motivo": "valor_divergente",
          "correto_seria": "Os testes começam em D27."
        },
        {
          "citacao": "data em que o protótipo fica disponível em D25",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A3",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A ação está ligada às peças fornecidas pela MetalForm, cuja entrega mudou; porém, o trecho não informa uma data ou outro fato que tenha ficado incorreto."
    },
    {
      "trecho_id": "ACTION_LOG.A4",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "entre D35 e D38",
          "motivo": "valor_divergente",
          "correto_seria": "A documentação ocorre entre D37 e D40."
        },
        {
          "citacao": "protótipo disponível em D24",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D27."
        },
        {
          "citacao": "validação concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R1",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "está no caminho crítico sem folga",
          "motivo": "premissa_alterada",
          "correto_seria": "O redutor tem 2 dias de folga; a MetalForm, com entrega em D22, passa a controlar o início da montagem."
        },
        {
          "citacao": "cada dia de atraso adia",
          "motivo": "premissa_alterada",
          "correto_seria": "Um atraso do redutor de até 2 dias é absorvido pela folga e não adia a liberação; atrasos adicionais podem adiá-la."
        },
        {
          "citacao": "Liberação de engenharia (D40)",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia ocorre em D42."
        },
        {
          "citacao": "e custa R$ 300,00 de gestão e instalação",
          "motivo": "premissa_alterada",
          "correto_seria": "O custo de gestão e instalação é R$ 300 por dia além de D40; atrasos do redutor só acrescentam custo depois de consumidos os 2 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R2",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O trecho trata do teste de vida e da janela de validação, cujo calendário foi deslocado; a afirmação condicional sobre ultrapassar os 10 dias e gerar cobrança continua válida."
    },
    {
      "trecho_id": "RISK_REGISTER.R3",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "tem apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A ElecBoard tem 3 dias de folga: a montagem começa em D22 e a entrega está prevista para D19."
        },
        {
          "citacao": "um atraso maior que isso passa a determinar o início da montagem",
          "motivo": "valor_divergente",
          "correto_seria": "Um atraso superior a 3 dias em relação à entrega prevista passa a afetar o início da montagem."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R4",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O item está ligado ao fornecedor MetalForm, cuja entrega mudou, mas nenhuma afirmação factual do trecho se tornou incorreta. A estimativa de custo não é verificável pelos dados fornecidos."
    },
    {
      "trecho_id": "DECISION_LOG.D1",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    },
    {
      "trecho_id": "DECISION_LOG.D2",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    },
    {
      "trecho_id": "DECISION_LOG.D3",
      "rotulo": "PRESERVAR",
      "informacoes": [],
      "observacao": "Registro histórico de decisão."
    }
  ]
}
